-- The two checklists published on 2026-10-14: washing when it feels like
-- too much (Self-Care) and avoided paperwork (Stress).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-14`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('when-washing-feels-like-too-much', 'When Washing Feels Like Too Much', 'For the stretch where showering, teeth and clean clothes have all slid, and the longer it goes the harder it gets. It helps you pick the smallest version of each, lower the bar on purpose, and get one thing done without a verdict attached.', 'Self-Care', '["Pick one thing only, not the whole list — a shower or your teeth, not both today.", "Use the wipes, dry shampoo or mouthwash — the shortcut version counts as done.", "Sit down in the shower if standing is too much — nobody is marking how you do it.", "Put clean clothes where you will see them — the decision is easier when it is already made.", "Set a two-minute limit and stop at it — a short attempt beats a postponed proper one.", "Put something loud on while you do it — the task is easier with company of any kind.", "Skip the catch-up on everything you missed — starting from today is the only option available.", "Tell someone if this has lasted weeks — a long stretch is worth saying out loud to a doctor."]'::jsonb, 'as needed', array['Self-Care', 'Depression']::text[], 1, '2026-10-14T16:00:00+00:00'::timestamptz),
  ('facing-the-paperwork-you-keep-avoiding', 'Facing the Paperwork You Keep Avoiding', 'For the form, claim or renewal that has been on the kitchen table for a month and grows heavier every time you walk past. It helps you find out what it actually needs, do one piece of it today, and stop the deadline from arriving first.', 'Stress', '["Read it once and write the deadline down — most of the dread is not knowing the date.", "List what you need to gather, not what to do — admin stalls on missing documents.", "Find the hardest document first — the rest is usually fifteen minutes after that.", "Fill in only the boxes you can answer now — a half-done form is further along than a blank one.", "Call the number on it with your question — the people on that line do this all day.", "Book twenty minutes for it in the calendar — avoided tasks need a slot, not more resolve.", "Do it at a table, not on your phone — the wrong setup is half the reason it stalls.", "Put it in the mail or hit send the same day — a finished form on the table is still unfinished."]'::jsonb, 'as needed', array['Stress', 'Habits']::text[], 1, '2026-10-14T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
